using ClosedXML.Excel;
using System.Text.Json.Nodes;
using Sales360.Domain;
namespace Sales360.Api;
public static class Imports
{
    public static void Map(RouteGroupBuilder api,Store store,Func<HttpContext,string> company,Func<HttpContext,string> actor,Action<HttpContext,string[]> role)
    {
        api.MapGet("/imports",async(HttpContext h)=>{await using var c=await store.Open();return await Store.Rows(c,"SELECT id,hash,status,errors,created_at FROM import_batch WHERE company_id=@p0 ORDER BY created_at DESC",company(h));});
        api.MapGet("/imports/template",()=>{
            using var book=new XLWorkbook();var cu=book.AddWorksheet("Customers");string[] ch=["code","name","email","trn"];for(int i=0;i<ch.Length;i++)cu.Cell(1,i+1).Value=ch[i];cu.Cell(2,1).Value="IMPORT-001";cu.Cell(2,2).Value="Synthetic Import Customer";cu.Cell(2,3).Value="billing@example.invalid";
            var pr=book.AddWorksheet("Projects");string[] ph=["code","name","customer_code","category","fee","location"];for(int i=0;i<ph.Length;i++)pr.Cell(1,i+1).Value=ph[i];pr.Cell(2,1).Value="IMP-9001";pr.Cell(2,2).Value="Imported Demonstration Project";pr.Cell(2,3).Value="IMPORT-001";pr.Cell(2,4).Value="Design";pr.Cell(2,5).Value=1000000;pr.Cell(2,6).Value="Dubai";
            foreach(var name in new[]{"Contracts_FeeSchedules","Invoices","Receipts_Allocations","OpeningBalances","Statements"}) {var s=book.AddWorksheet(name);s.Cell(1,1).Value="Reference only - financial import is not enabled in this increment";}
            foreach(var s in book.Worksheets){s.Row(1).Style.Font.Bold=true;s.Columns().AdjustToContents();}using var ms=new MemoryStream();book.SaveAs(ms);return Results.File(ms.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","SALES360-import-template.xlsx");
        });
        api.MapPost("/imports/preview",async(HttpContext h)=>{role(h,["Accountant","Finance Administrator","Super user"]);var form=await h.Request.ReadFormAsync();var file=form.Files.GetFile("file")??throw new RuleException("Choose an XLSX workbook.");Billing.Require(file.Length<=10*1024*1024&&file.FileName.EndsWith(".xlsx",StringComparison.OrdinalIgnoreCase),"Only XLSX up to 10 MB is supported. Macros are not accepted.");using var ms=new MemoryStream();await file.CopyToAsync(ms);var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(ms.ToArray()));ms.Position=0;
            // ZIP bomb guard before the workbook parser.
            using(var zip=new System.IO.Compression.ZipArchive(ms,System.IO.Compression.ZipArchiveMode.Read,true)) {Billing.Require(zip.Entries.Sum(x=>x.Length)<50*1024*1024&&zip.Entries.Count<2000,"Workbook expanded size exceeds safe limit.");Billing.Require(!zip.Entries.Any(x=>x.FullName.Contains("externalLinks/",StringComparison.OrdinalIgnoreCase)),"Remove external workbook links before import.");}ms.Position=0;
            var mapping=JsonNode.Parse(form["mapping"].FirstOrDefault()??"{}")!;var payload=new JsonObject();var errors=new JsonArray();using var book=new XLWorkbook(ms);
            foreach(var type in new[]{"Customers","Projects"}) {var name=mapping[type]?["sheet"]?.ToString()??type;var rows=new JsonArray();payload[type]=rows;if(!book.TryGetWorksheet(name,out var sheet)){errors.Add($"{type}: sheet '{name}' not found. Set a sheet mapping.");continue;}var last=sheet.LastRowUsed()?.RowNumber()??1;Billing.Require(last<=10001,"Preview limited to 10,000 rows per sheet.");var fields=type=="Customers"?new[]{"code","name","email","trn"}:new[]{"code","name","customer_code","category","fee","location"};var headers=sheet.Row(1).CellsUsed().ToDictionary(x=>x.GetString().Trim(),x=>x.Address.ColumnNumber,StringComparer.OrdinalIgnoreCase);
                for(var row=2;row<=last;row++){if(sheet.Row(row).IsEmpty())continue;var item=new JsonObject{["row"]=row};foreach(var field in fields){var header=mapping[type]?["columns"]?[field]?.ToString()??field;if(headers.TryGetValue(header,out var col)){var cell=sheet.Cell(row,col);if(cell.HasFormula)errors.Add($"{name}!{row} {field}: formula cells require explicit values.");item[field]=cell.GetFormattedString().Trim();}else item[field]="";}if(item.Text("code")==""||item.Text("name")=="")errors.Add($"{name}!{row}: code and name required.");if(type=="Projects"&&(!decimal.TryParse(item.Text("fee"),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out var fee)||fee<=0||!Billing.Categories.Contains(item.Text("category"))))errors.Add($"{name}!{row}: positive fee and one of the five service categories required.");rows.Add(item);}
                if(rows.Select(x=>x!.Text("code")).Distinct().Count()!=rows.Count)errors.Add($"{name}: duplicate source codes.");
            }
            return await store.Transaction(company(h),async c=>{foreach(var p in payload["Projects"]!.AsArray()){var code=p!.Text("customer_code");if(!payload["Customers"]!.AsArray().Any(x=>x!.Text("code")==code)&&(await Store.Rows(c,"SELECT id FROM customer WHERE company_id=@p0 AND code=@p1",company(h),code)).Count==0)errors.Add($"Projects!{p!.Text("row")}: unknown customer_code {code}.");}
                var prior=await Store.Rows(c,"SELECT * FROM import_batch WHERE company_id=@p0 AND hash=@p1",company(h),hash);if(prior.Count>0)return prior[0]!;var id=Guid.NewGuid().ToString("N");await Store.Exec(c,"INSERT INTO import_batch(id,company_id,hash,payload,errors) VALUES(@p0,@p1,@p2,@p3::jsonb,@p4::jsonb)",id,company(h),hash,payload.ToJsonString(),errors.ToJsonString());await Store.Audit(c,company(h),actor(h),"Workbook preview created",id,new{hash});return await Store.One(c,"SELECT * FROM import_batch WHERE id=@p0",id);});
        }).DisableAntiforgery();
        api.MapPost("/imports/{id}/commit",async(HttpContext h,string id)=>{role(h,["Accountant","Finance Administrator","Super user"]);return await store.Transaction(company(h),async c=>{var batch=await Store.One(c,"SELECT * FROM import_batch WHERE company_id=@p0 AND id=@p1",company(h),id);if(batch.Text("status")=="Committed")return new{created=0,message="Identical import already committed."};Billing.Require(batch["errors"]!.AsArray().Count==0,"Resolve all preview errors before import.");var count=0;var payload=batch["payload"]!;
            foreach(var cu in payload["Customers"]!.AsArray()){var x=cu!;var existing=await Store.Rows(c,"SELECT * FROM customer WHERE company_id=@p0 AND code=@p1",company(h),x.Text("code"));if(existing.Count>0){Billing.Require(existing[0]!.Text("name")==x.Text("name"),"Customer code conflicts with a different legal name. Review manually.");continue;}var trn=x.Text("trn");Billing.Require(trn==""||System.Text.RegularExpressions.Regex.IsMatch(trn,"^[0-9]{15}$"),"Imported TRN must be 15 digits.");await Store.Exec(c,"INSERT INTO customer(id,company_id,code,name,email,trn) VALUES(@p0,@p1,@p2,@p3,@p4,@p5)",Guid.NewGuid().ToString("N"),company(h),x.Text("code"),x.Text("name"),x.Text("email"),trn);count++;}
            foreach(var pr in payload["Projects"]!.AsArray()){var x=pr!;var customer=await Store.One(c,"SELECT id FROM customer WHERE company_id=@p0 AND code=@p1",company(h),x.Text("customer_code"));var existing=await Store.Rows(c,"SELECT * FROM project WHERE company_id=@p0 AND code=@p1",company(h),x.Text("code"));if(existing.Count>0){Billing.Require(existing[0]!.Text("customer_id")==customer.Text("id")&&existing[0]!.Text("name")==x.Text("name")&&existing[0]!.Decimal("fee")==x.Decimal("fee"),"Project code conflicts with a different customer, name or fee.");continue;}await Store.Exec(c,"INSERT INTO project(id,company_id,customer_id,code,name,category,fee,location,stages) VALUES(@p0,@p1,@p2,@p3,@p4,@p5,@p6,@p7,@p8::jsonb)",Guid.NewGuid().ToString("N"),company(h),customer.Text("id"),x.Text("code"),x.Text("name"),x.Text("category"),x.Decimal("fee"),x.Text("location"),Seed.Stages());count++;}
            await Store.Exec(c,"UPDATE import_batch SET status='Committed' WHERE id=@p0",id);await Store.Audit(c,company(h),actor(h),"Reviewed workbook imported",id,new{created=count,ledgerEntries=0});return new{created=count,message="Customer/project masters reconciled. Financial sheets are reference only; no ledger entries imported."};});});
    }
}
